from collections import Counter
def transform(g):
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    cells=[(r,c,v) for r,row in enumerate(g) for c,v in enumerate(row) if v!=bg]
    cnt=Counter(v for _,_,v in cells)
    marker=min(cnt,key=cnt.get)  # scattered singleton color
    tcells=[(r,c) for r,c,v in cells if v!=marker]
    r0=min(r for r,_ in tcells); r1=max(r for r,_ in tcells)
    c0=min(c for _,c in tcells); c1=max(c for _,c in tcells)
    tm=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    H,W=len(g),len(g[0]); h,w=len(tm),len(tm[0])
    ar,ac=(h-1)//2,(w-1)//2
    out=[row[:] for row in g]
    for r,row in enumerate(g):
        for c,v in enumerate(row):
            if v==marker:
                for rr in range(h):
                    for cc in range(w):
                        R,C=r-ar+rr,c-ac+cc
                        if 0<=R<H and 0<=C<W: out[R][C]=tm[rr][cc]
    return out
